-- Create "devices" table
CREATE TABLE `devices` (`id` bigint NOT NULL AUTO_INCREMENT, `installation_id` varchar(128) NOT NULL, `login_id` varchar(256) NOT NULL, `platform` enum('ios','android') NOT NULL, `push_token` varchar(512) NOT NULL, `device_token` varchar(4096) NULL, `app_id` varchar(256) NULL, `app_version` varchar(64) NULL, `build_number` varchar(64) NULL, `os_version` varchar(64) NULL, `device_model` varchar(128) NULL, `locale` varchar(32) NULL, `created_at` timestamp NOT NULL, `updated_at` timestamp NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `installation_id` (`installation_id`), INDEX `device_login_id` (`login_id`), INDEX `device_push_token` (`push_token`));
